        /// </summary>
        [DllImport(__DllName, EntryPoint = "pdfoxide_editor_open_from_bytes_with_password", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void* pdfoxide_editor_open_from_bytes_with_password(byte* data, nuint len, byte* password, int* error_code);

        /// <summary>
        ///  Retrieve the last error message.
        ///
        ///  # Returns
        ///  * Pointer to allocated C string containing the error message, or NULL if no error
        ///
        ///  # Safety
        ///  The returned pointer must be freed using `pdf_string_free()`.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "pdf_last_error_message", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern byte* pdf_last_error_message();

        /// <summary>
        ///  Free a string allocated by the FFI functions.
        ///
        ///  # Arguments
        ///  * `ptr` - Pointer to the string to free
        ///
        ///  # Safety
        ///  This must only be called with pointers returned by FFI functions
        ///  (not arbitrary memory).
        /// </summary>
        [DllImport(__DllName, EntryPoint = "pdf_string_free", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void pdf_string_free(byte* ptr);

        /// <summary>
        ///  Get the length of a string returned by FFI functions.
        ///
        ///  # Arguments
        ///  * `ptr` - Pointer to the string
        ///
        ///  # Returns
        ///  * Length in bytes, or 0 if ptr is NULL
        /// </summary>
        [DllImport(__DllName, EntryPoint = "pdf_get_string_len", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int pdf_get_string_len(byte* ptr);


